-- CityGuide business records. Industry-independent by design: `industry` is a column,
-- not a table name, so the same engine runs dentists or restaurants without a rebuild.
-- Source: Overture Maps Places via api.overturemapsapi.com, CDLA-Permissive-2.0.
-- PROVENANCE IS NOT OPTIONAL. src/src_id/src_time/license travel with every row, so a later
-- conflict can be resolved by asking which source said what and when.
DROP TABLE IF EXISTS cg_business;
CREATE TABLE cg_business (
  id          TEXT PRIMARY KEY,      -- Overture GERS id; stable across releases
  industry    TEXT NOT NULL,
  name        TEXT,
  category    TEXT,
  alternates  TEXT,                  -- pipe-joined; how we spot brow bars filed under tattoo
  confidence  REAL,
  status      TEXT,                  -- Overture operating_status when present
  lat         REAL, lng REAL,
  street      TEXT, locality TEXT, region TEXT, postcode TEXT,
  website     TEXT, email TEXT, phone TEXT, social TEXT,
  src         TEXT, src_id TEXT, src_time TEXT, license TEXT,
  -- ONBOARDING STATE. Nothing here is set at import; every field is written by us later.
  crawled_at  TEXT,
  email_found TEXT,                  -- an email the CRAWL found, kept apart from Overture's
  contacted_at TEXT,
  outcome     TEXT,                  -- PAID | NOT_NOW | DEFERRED | STOPPED | ABANDONED
  pta         TEXT,                  -- set only when they become an entity, never at import
  claimed_at  TEXT,
  imported_at TEXT NOT NULL
);
CREATE INDEX cg_region   ON cg_business(region);
CREATE INDEX cg_email    ON cg_business(email);
CREATE INDEX cg_contacted ON cg_business(contacted_at);
CREATE INDEX cg_dup      ON cg_business(street, locality);

